<?php
/**
 * Esquema cerrado de las plantillas del Theme Builder de Divi 5 que el conector deja escribir.
 *
 * @package NexoDev\NexoMCP
 */

declare(strict_types=1);

namespace NexoDev\NexoMCP\Builders;

/**
 * Decisiones D4, D5, D6 y D8 de L2 de `odd/tasks/divi-theme-builder.md` (S6 y S7).
 *
 * Divi guarda una plantilla como un post `et_template` publicado con estas metas (una fila por condición en las listas):
 * `_et_use_on` y `_et_exclude_from` (ids de texto separados por `:`), `_et_default` y `_et_enabled` ('1'/'0'),
 * `_et_autogenerated_title` y, por cada área `header|body|footer`, `_et_<área>_layout_id` (0 = sin layout propio) y
 * `_et_<área>_layout_enabled` ('0' = «ocultar esa área»). Aquí se arma SÓLO eso: ninguna otra meta.
 *
 * Divi no valida los ids de asignación (guarda cualquier cadena y nunca coincide) y elige UNA sola plantilla por petición
 * (ver {@see self::winner()}). Por eso el catálogo es cerrado y todo se rechaza, nunca se sanea: ids de contenido, de
 * término y de usuario que existen (el contenido, además `publish`), tipos y taxonomías públicos, WooCommerce sólo si
 * está activo, y layouts `publish` del tipo de su área. Se rechazan `archive:user:role:*`, `children:id:` y todo lo que no
 * esté en el catálogo.
 *
 * Las fuentes de WordPress son funciones inyectables con una fuente de producción por omisión (protegida con
 * `function_exists`). Cualquier excepción de una fuente cuenta como «no existe»: ni la validación ni las lecturas lanzan
 * (lección L7 de `divi-condiciones.md`).
 */
final class DiviThemeBuilderSchema {

	public const CODE_INVALID = 'nexo_mcp_divi_template_invalid';

	public const CODE_SITE_WIDE = 'nexo_mcp_divi_template_site_wide';

	public const CODE_BODY = 'nexo_mcp_divi_template_body_replaces_content';

	public const MAX_CONTEXTS = 20;

	public const MAX_TITLE = 100;

	private const MAX_SUMMARY = 50;

	private const SLOTS = array( 'header', 'body', 'footer' );

	private const KEYS = array( 'title', 'enabled', 'default', 'use_on', 'exclude_from', 'header', 'body', 'footer', 'confirm_site_wide', 'allow_without_post_content' );

	/**
	 * Metas `_et_*` de una plantilla de Divi que no cambian lo que se representa (se aceptan con cualquier valor).
	 *
	 * @var array<int, string>
	 */
	private const IGNORED_METAS = array( '_et_autogenerated_title', '_et_onboarding_created' );

	/**
	 * Catálogo (D4): patrón, prioridad de Divi (mayor gana), si es de sitio entero y si necesita WooCommerce.
	 *
	 * @var array<int, array{pattern: string, priority: int, site_wide: bool, needs_woocommerce: bool}>
	 */
