	/**
	 * Tipo de contenido: fn( string ): array{public: bool, label: string}|null.
	 *
	 * @var callable
	 */
	private $post_types;

	/**
	 * Taxonomía: fn( string ): array{public: bool, label: string}|null.
	 *
	 * @var callable
	 */
	private $taxonomies;

	/**
	 * Nombre de un término o null: fn( int, string ): string|null.
	 *
	 * @var callable
	 */
	private $term_label;

	/**
	 * Entrada publicada: fn( int ): array{type: string, label: string}|null.
	 *
	 * @var callable
	 */
	private $posts;

	/**
	 * Nombre de un usuario o null: fn( int ): string|null.
	 *
	 * @var callable
	 */
	private $users;

	/**
	 * WooCommerce activo: fn(): bool.
	 *
	 * @var callable
	 */
	private $woo_active;

	/**
	 * Layout publicado del tipo de su área: fn( int, string ): bool.
	 *
	 * @var callable
	 */
	private $layouts;

	/**
	 * El layout lleva `divi/post-content`: fn( int ): bool.
	 *
	 * @var callable
	 */
	private $has_post_content;

	/**
	 * Construye el esquema; cada función tiene su fuente de producción por omisión.
	 *
	 * @param callable|null $post_types       fn( string ): array{public: bool, label: string}|null.
	 * @param callable|null $taxonomies       fn( string ): array{public: bool, label: string}|null.
	 * @param callable|null $term_label       fn( int, string ): string|null.
	 * @param callable|null $posts            fn( int ): array{type: string, label: string}|null (sólo publicadas).
	 * @param callable|null $users            fn( int ): string|null.
	 * @param callable|null $woo_active       fn(): bool.
	 * @param callable|null $layouts          fn( int, string ): bool (publicado y del tipo `et_<área>_layout`).
	 * @param callable|null $has_post_content fn( int ): bool.
	 */
	public function __construct( ?callable $post_types = null, ?callable $taxonomies = null, ?callable $term_label = null, ?callable $posts = null, ?callable $users = null, ?callable $woo_active = null, ?callable $layouts = null, ?callable $has_post_content = null ) {
		$this->post_types       = $post_types ?? array( self::class, 'registered_post_type' );
		$this->taxonomies       = $taxonomies ?? array( self::class, 'registered_taxonomy' );
		$this->term_label       = $term_label ?? array( self::class, 'registered_term_label' );
		$this->posts            = $posts ?? array( self::class, 'registered_post' );
		$this->users            = $users ?? array( self::class, 'registered_user' );
		$this->woo_active       = $woo_active ?? static fn(): bool => class_exists( 'WooCommerce' );
		$this->layouts          = $layouts ?? array( self::class, 'registered_layout' );
		$this->has_post_content = $has_post_content ?? array( self::class, 'layout_has_post_content' );
	}

	/**
	 * Valida la plantilla del cliente (forma, catálogo, reglas de S6) y devuelve los parámetros normalizados.
	 *
	 * @param mixed $input `{title, enabled?, default?, use_on?, exclude_from?, header|body|footer?: {layout_id, enabled}, confirm_site_wide?, allow_without_post_content?}`.
	 *
	 * @return array<string, mixed>|\WP_Error
	 */
	public function validate( $input ) {
		$params = $this->check( $input );

		if ( $params instanceof \WP_Error ) {
			return $params;
		}

		if ( $this->is_site_wide( $params['default'], $params['use_on'] ) && true !== $params['confirm_site_wide'] ) {
			return new \WP_Error(
				self::CODE_SITE_WIDE,
				'confirm_site_wide: ' . __( 'una plantilla por defecto, o asignada a un …:all, archive:all o 404, cambia todo el sitio. Repite la llamada con confirm_site_wide: true si es lo que quieres.', 'nexo-mcp' ),
				array( 'path' => 'confirm_site_wide' )
			);
		}

		$body = $params['body'];

		if ( null !== $body['layout_id'] && $body['enabled'] && ! $params['allow_without_post_content'] && $this->replaces_content( $params ) && true !== $this->call( $this->has_post_content, $body['layout_id'] ) ) {
			return new \WP_Error(
				self::CODE_BODY,
				'body.layout_id: ' . __( 'el cuerpo no lleva el módulo divi/post-content: sustituiría el contenido de las páginas, entradas y pantallas de WooCommerce a las que se asigna (el carrito, por ejemplo, dejaría de verse). Añade divi/post-content o repite con allow_without_post_content: true.', 'nexo-mcp' ),
				array( 'path' => 'body.layout_id' )
			);
		}

		return $params;
	}

	/**
	 * Metas `_et_*` de la plantilla ya validada, con los valores y la forma con que Divi las guarda: las listas, una fila
	 * de meta por elemento; el resto, texto. Las marcas de confirmación nunca se guardan.
	 *
	 * @param array<string, mixed> $params Resultado de {@see self::validate()}.
	 *
	 * @return array<string, string|array<int, string>>
	 */
	public function stored( array $params ): array {
		$metas = array(
			'_et_default'             => $params['default'] ? '1' : '0',
			'_et_enabled'             => $params['enabled'] ? '1' : '0',
			'_et_autogenerated_title' => '0',
			'_et_use_on'              => array_values( $params['use_on'] ),
			'_et_exclude_from'        => array_values( $params['exclude_from'] ),
		);

		foreach ( self::SLOTS as $slot ) {
			$metas[ '_et_' . $slot . '_layout_id' ]      = (string) ( $params[ $slot ]['layout_id'] ?? 0 );
			$metas[ '_et_' . $slot . '_layout_enabled' ] = $params[ $slot ]['enabled'] ? '1' : '0';
		}

		return $metas;
	}

	/**
	 * Los parámetros de una plantilla guardada si el conector puede representarla por completo (y reescribirla sin
	 * perder nada), o null si es ajena, rara o ya no es válida. Nunca lanza.
	 *
	 * @param mixed $metas Metas del post `et_template`: clave => valor (texto, o lista para las condiciones).
	 * @param mixed $title Título del post.
	 *
	 * @return array<string, mixed>|null
	 */
	public function valid_stored( $metas, $title = '' ): ?array {
		return $this->safely( fn(): ?array => $this->recognise( $metas, $title ) );
	}

	/**
	 * Resumen seguro de cualquier plantilla guardada (propia, del Visual Builder o rara). De los ids de asignación sólo se
	 * muestran los de forma segura (se conservan los desconocidos, marcados `supported: false`); nunca textos libres. Nunca
	 * lanza, ni aunque lancen las fuentes de WordPress.
	 *
	 * @param mixed $metas Metas del post `et_template`.
	 * @param mixed $title Título del post.
	 *
	 * @return array{ours: bool, title: string, enabled: bool|null, default: bool, site_wide: bool, use_on: array<int, array{id: string|null, supported: bool, priority: int|null}>, exclude_from: array<int, array{id: string|null, supported: bool, priority: int|null}>, header: array{layout_id: int|null, enabled: bool}, body: array{layout_id: int|null, enabled: bool}, footer: array{layout_id: int|null, enabled: bool}}
	 */
	public function summary( $metas, $title = '' ): array {
		$metas   = is_array( $metas ) ? $metas : array();
		$default = '1' === ( $metas['_et_default'] ?? null );
		$enabled = $metas['_et_enabled'] ?? null;
		$use_on  = self::raw_list( $metas['_et_use_on'] ?? null );
		$entries = fn( array $items ): array => array_map( fn( $id ): array => $this->summarise_context( $id ), array_slice( $items, 0, self::MAX_SUMMARY ) );
		$wide    = $default;

		foreach ( $use_on as $context ) {
			$parsed = self::parse( $context );
			$wide   = $wide || ( null !== $parsed && $parsed['site_wide'] );
		}

		$out = array(
			'ours'         => null !== $this->valid_stored( $metas, $title ),
			'title'        => is_string( $title ) ? self::display_text( $title ) : '',
			'enabled'      => '1' === $enabled ? true : ( '0' === $enabled ? false : null ),
			'default'      => $default,
			'site_wide'    => $wide,
			'use_on'       => $entries( $use_on ),
			'exclude_from' => $entries( self::raw_list( $metas['_et_exclude_from'] ?? null ) ),
		);

		foreach ( self::SLOTS as $slot ) {
			$id           = $metas[ '_et_' . $slot . '_layout_id' ] ?? null;
			$out[ $slot ] = array(
				'layout_id' => is_string( $id ) && 1 === preg_match( '/^[1-9][0-9]{0,9}\z/', $id ) ? (int) $id : null,
				'enabled'   => '0' !== ( $metas[ '_et_' . $slot . '_layout_enabled' ] ?? null ),
			);
		}

		return $out;
	}

	/**
	 * Prioridad de Divi de un contexto del catálogo (mayor gana), o null si no está en el catálogo. No consulta nada.
	 *
	 * @param mixed $context Contexto.
	 */
	public static function priority( $context ): ?int {
		$parsed = self::parse( $context );

		return null === $parsed ? null : $parsed['priority'];
	}

	/**
	 * Patrones del catálogo con su prioridad, para listarlos al cliente (WooCommerce sólo si está activo).
	 *
	 * @return array<int, array{pattern: string, priority: int, site_wide: bool, needs_woocommerce: bool}>
	 */
	public function catalog(): array {
		$woo = true === $this->call( $this->woo_active );

		return array_values( array_filter( self::CATALOG, static fn( array $entry ): bool => $woo || ! $entry['needs_woocommerce'] ) );
	}

	/**
	 * Qué plantilla gana en una petición (Divi elige UNA, no las fusiona): se descartan las deshabilitadas y las que
	 * cumplen alguna `exclude_from`; de las que quedan gana la de `use_on` de mayor prioridad (empate: la de clave menor);
	 * si ninguna aplica, la plantilla por defecto habilitada.
	 *
	 * @param mixed              $templates Lista de `{key, enabled, default, use_on[], exclude_from[]}`; lo que no encaje se ignora.
	 * @param array<int, string> $matching  Contextos del catálogo que cumple la petición (por ejemplo `homepage`, `singular:post_type:page:all`).
	 *
	 * @return array{key: string|int, via: string, context: string|null, priority: int}|null
	 */
	public function winner( $templates, array $matching ): ?array {
		$best    = null;
		$default = null;

		foreach ( self::usable( $templates ) as $template ) {
			if ( array() !== array_intersect( $template['exclude_from'], $matching ) ) {
				continue;
			}

			foreach ( $template['use_on'] as $context ) {
				$priority = self::priority( $context );

				if ( null === $priority || ! in_array( $context, $matching, true ) ) {
					continue;
				}

				if ( null === $best || $priority > $best['priority'] || ( $priority === $best['priority'] && strnatcmp( (string) $template['key'], (string) $best['key'] ) < 0 ) ) {
					$best = array(
						'key'      => $template['key'],
						'via'      => 'use_on',
						'context'  => $context,
						'priority' => $priority,
					);
				}
			}

			if ( $template['default'] && ( null === $default || strnatcmp( (string) $template['key'], (string) $default['key'] ) < 0 ) ) {
				$default = array(
					'key'      => $template['key'],
					'via'      => 'default',
					'context'  => null,
					'priority' => 0,
				);
			}
		}

		return $best ?? $default;
	}

	/**
	 * Qué plantilla tapa a cuál: por cada contexto (o la plantilla por defecto, que cubre todo el sitio) que otra plantilla
	 * habilitada recorta con un contexto más específico y de mayor prioridad (`archive:all` → `archive:post_type:…`,
	 * `…:all` → `…:id:…`). No evalúa `exclude_from` ni solapes que no sean de inclusión.
	 *
	 * @param mixed $templates Lista de `{key, enabled, default, use_on[], exclude_from[]}`; lo que no encaje se ignora.
	 *
	 * @return array<int, array{template: string|int, context: string|null, priority: int, covered_by: string|int, by_context: string, by_priority: int}>
	 */
	public function shadows( $templates ): array {
		$list = array_values( array_filter( self::usable( $templates ), static fn( array $t ): bool => $t['enabled'] ) );
		$out  = array();

		foreach ( $list as $broad ) {
			$sources = array();

			if ( $broad['default'] ) {
				$sources[] = null;
			}

			foreach ( $broad['use_on'] as $context ) {
				if ( null !== self::priority( $context ) ) {
					$sources[] = $context;
				}
			}

			foreach ( $sources as $context ) {
				$low = null === $context ? 0 : (int) self::priority( $context );

				foreach ( $list as $narrow ) {
					if ( $narrow['key'] === $broad['key'] ) {
						continue;
					}

					$best = null;

					foreach ( $narrow['use_on'] as $other ) {
						$priority = self::priority( $other );

						if ( null === $priority || $priority <= $low || ( null !== $context && ! self::contains( $context, $other ) ) ) {
							continue;
						}

						if ( null === $best || $priority > $best['priority'] ) {
							$best = array(
								'context'  => $other,
								'priority' => $priority,
							);
						}
					}

					if ( null !== $best ) {
						$out[] = array(
							'template'    => $broad['key'],
							'context'     => $context,
							'priority'    => $low,
							'covered_by'  => $narrow['key'],
							'by_context'  => $best['context'],
							'by_priority' => $best['priority'],
						);
					}
				}
			}
		}

		return $out;
	}

	/**
	 * Tipo de contenido registrado (fuente de producción).
	 *
	 * @param string $type Tipo.
	 *
	 * @return array{public: bool, label: string}|null
	 */
	public static function registered_post_type( string $type ): ?array {
		return function_exists( 'get_post_type_object' ) ? DiviLoopSchema::registered_post_type( $type ) : null;
	}

	/**
	 * Taxonomía registrada (fuente de producción): pública o con interfaz.
	 *
	 * @param string $taxonomy Taxonomía.
	 *
	 * @return array{public: bool, label: string}|null
	 */
	public static function registered_taxonomy( string $taxonomy ): ?array {
		if ( ! function_exists( 'get_taxonomy' ) ) {
			return null;
		}

		$object = get_taxonomy( $taxonomy );

		if ( ! $object instanceof \WP_Taxonomy ) {
			return null;
		}

		return array(
			'public' => (bool) ( $object->public || $object->show_ui ),
			'label'  => (string) ( $object->labels->name ?? $object->label ),
		);
	}

	/**
	 * Nombre de un término (fuente de producción), o null.
	 *
	 * @param int    $id       Término.
	 * @param string $taxonomy Taxonomía.
	 */
	public static function registered_term_label( int $id, string $taxonomy ): ?string {
		return function_exists( 'get_term' ) ? DiviLoopSchema::registered_term_label( $id, $taxonomy ) : null;
	}

	/**
	 * Entrada publicada (fuente de producción), o null.
	 *
	 * @param int $id Id.
	 *
	 * @return array{type: string, label: string}|null
	 */
	public static function registered_post( int $id ): ?array {
		return function_exists( 'get_post' ) ? DiviConditionsSchema::registered_post( $id ) : null;
	}

	/**
	 * Nombre de un usuario (fuente de producción), o null si no existe.
	 *
	 * @param int $id Id.
	 */
	public static function registered_user( int $id ): ?string {
		if ( ! function_exists( 'get_userdata' ) ) {
			return null;
		}

		$user = get_userdata( $id );

		return $user instanceof \WP_User ? (string) $user->display_name : null;
	}

	/**
	 * Layout publicado del tipo de su área (fuente de producción): un layout no `publish` también se muestra a los
	 * visitantes, por eso aquí se exige `publish` (L2, riesgo c).
	 *
	 * @param int    $id   Id.
	 * @param string $slot `header`, `body` o `footer`.
	 */
	public static function registered_layout( int $id, string $slot ): bool {
		if ( ! function_exists( 'get_post' ) ) {
			return false;
		}

		$post = get_post( $id );

		return $post instanceof \WP_Post && 'publish' === $post->post_status && 'et_' . $slot . '_layout' === $post->post_type;
	}

	/**
	 * Si el contenido del layout lleva el bloque `divi/post-content` (o el de ancho completo).
	 *
	 * @param int $id Id.
	 */
	public static function layout_has_post_content( int $id ): bool {
		if ( ! function_exists( 'get_post' ) ) {
			return false;
		}

		$post = get_post( $id );

		return $post instanceof \WP_Post && 1 === preg_match( '/<!--\s+wp:divi\/(?:fullwidth-)?post-content[\s}\/]/', $post->post_content );
	}

	/**
	 * Valida la forma y el catálogo, sin las reglas de S6.
	 *
	 * @param mixed $input Entrada.
	 *
	 * @return array<string, mixed>|\WP_Error
	 */
	private function check( $input ) {
		if ( ! is_array( $input ) || array() === $input || array_is_list( $input ) ) {
			return $this->invalid( 'template', __( 'debe ser un objeto {title, enabled, default, use_on, exclude_from, header, body, footer}.', 'nexo-mcp' ) );
		}

		foreach ( array_keys( $input ) as $key ) {
			if ( ! in_array( (string) $key, self::KEYS, true ) ) {
				return $this->invalid( (string) $key, sprintf( /* translators: %s: claves. */ __( 'no se admite. Admitidas: %s.', 'nexo-mcp' ), implode( ', ', self::KEYS ) ) );
			}
		}

		$title = $this->check_title( $input['title'] ?? null );

		if ( $title instanceof \WP_Error ) {
			return $title;
		}

		$out = array( 'title' => $title );

		foreach ( array( 'enabled', 'default' ) as $flag ) {
			$value = $input[ $flag ] ?? false;

			if ( ! is_bool( $value ) ) {
				return $this->invalid( $flag, __( 'debe ser un booleano (true o false).', 'nexo-mcp' ) );
			}

			$out[ $flag ] = $value;
		}

		$use_on = $this->check_contexts( 'use_on', $input['use_on'] ?? array() );

		if ( $use_on instanceof \WP_Error ) {
			return $use_on;
		}

		$exclude = $this->check_contexts( 'exclude_from', $input['exclude_from'] ?? array() );

		if ( $exclude instanceof \WP_Error ) {
			return $exclude;
		}

		foreach ( $exclude as $index => $context ) {
			if ( in_array( $context, $use_on, true ) ) {
				return $this->invalid( 'exclude_from.' . $index, __( 'ya está en use_on: la plantilla no se aplicaría nunca a ese contexto.', 'nexo-mcp' ) );
			}
		}

		$out['use_on']       = $use_on;
		$out['exclude_from'] = $exclude;

		foreach ( self::SLOTS as $slot ) {
			$checked = $this->check_slot( $slot, $input[ $slot ] ?? array() );

			if ( $checked instanceof \WP_Error ) {
				return $checked;
			}

			$out[ $slot ] = $checked;
		}

		foreach ( array( 'confirm_site_wide', 'allow_without_post_content' ) as $flag ) {
			$value = $input[ $flag ] ?? false;

			if ( ! is_bool( $value ) ) {
				return $this->invalid( $flag, __( 'debe ser un booleano (true o false).', 'nexo-mcp' ) );
			}

			$out[ $flag ] = $value;
		}

		return $out;
	}

	/**
	 * Título: texto de 1 a 100 caracteres, sin control ni `< >` (Divi aplica `sanitize_text_field`).
	 *
	 * @param mixed $title Valor recibido.
	 *
	 * @return string|\WP_Error
	 */
	private function check_title( $title ) {
		$text = is_string( $title ) ? trim( $title ) : '';

		if ( '' === $text || 1 === preg_match( '/[\x00-\x1F\x7F<>]/u', $text ) || 1 !== preg_match( '//u', $text ) ) {
			return $this->invalid( 'title', __( 'es obligatorio: un texto sin saltos de línea ni < >.', 'nexo-mcp' ) );
		}

		if ( mb_strlen( $text, 'UTF-8' ) > self::MAX_TITLE ) {
			return $this->invalid( 'title', sprintf( /* translators: %d: máximo. */ __( 'admite hasta %d caracteres.', 'nexo-mcp' ), self::MAX_TITLE ) );
		}

		return $text;
	}

	/**
	 * Lista de contextos del catálogo, sin repetidos y de hasta 20.
	 *
	 * @param string $path  `use_on` o `exclude_from`.
	 * @param mixed  $items Valor recibido.
	 *
	 * @return array<int, string>|\WP_Error
	 */
	private function check_contexts( string $path, $items ) {
		if ( ! is_array( $items ) || ( array() !== $items && ! array_is_list( $items ) ) ) {
			return $this->invalid( $path, __( 'debe ser una lista de contextos del catálogo (vacía si no hay).', 'nexo-mcp' ) );
		}

		if ( count( $items ) > self::MAX_CONTEXTS ) {
			return $this->invalid( $path, sprintf( /* translators: %d: máximo. */ __( 'admite hasta %d contextos.', 'nexo-mcp' ), self::MAX_CONTEXTS ) );
		}

		$out = array();

		foreach ( $items as $index => $context ) {
			$checked = $this->check_context( $path . '.' . $index, $context );

			if ( $checked instanceof \WP_Error ) {
				return $checked;
			}

			if ( in_array( $checked, $out, true ) ) {
				return $this->invalid( $path . '.' . $index, __( 'está repetido.', 'nexo-mcp' ) );
			}

			$out[] = $checked;
		}

		return $out;
	}

	/**
	 * Un contexto: del catálogo, y con tipos, taxonomías, términos, usuarios y contenido que existen.
	 *
	 * @param string $at      Ruta.
	 * @param mixed  $context Valor recibido.
	 *
	 * @return string|\WP_Error
	 */
	private function check_context( string $at, $context ) {
		$parsed = self::parse( $context );

		if ( null === $parsed || ! is_string( $context ) ) {
			return $this->invalid( $at, __( 'no está en el catálogo (homepage, 404, search, singular:post_type:<tipo>:all|id:<id>, singular:taxonomy:<tax>:term:id:<id>, archive:all, archive:post_type:<tipo>, archive:taxonomy:<tax>:all|term:id:<id>, archive:user:all|id:<id>, archive:date:all y woocommerce:shop|cart|checkout|my_account).', 'nexo-mcp' ) );
		}

		foreach ( $parsed['checks'] as $check ) {
			$ok = match ( $check[0] ) {
				'woo'       => true === $this->call( $this->woo_active ),
				'post_type' => $this->is_public( $this->call( $this->post_types, $check[1] ) ) && 'attachment' !== $check[1],
				'taxonomy'  => $this->is_public( $this->call( $this->taxonomies, $check[1] ) ),
				'post'      => $this->post_is( $this->call( $this->posts, (int) $check[1] ), $check[2] ),
				'term'      => is_string( $this->call( $this->term_label, (int) $check[1], $check[2] ) ),
				default     => is_string( $this->call( $this->users, (int) $check[1] ) ),
			};

			if ( ! $ok ) {
				return $this->invalid( $at, sprintf( /* translators: %s: contexto. */ __( '«%s» no existe, no está publicado o no está disponible (WooCommerce, tipo, taxonomía, término, usuario o contenido).', 'nexo-mcp' ), $context ) );
			}
		}

		return $context;
	}

	/**
	 * Un área: `{layout_id: int|null, enabled: bool}`; sin ella, sin layout propio y visible.
	 *
	 * @param string $slot  `header`, `body` o `footer`.
	 * @param mixed  $value Valor recibido.
	 *
	 * @return array{layout_id: int|null, enabled: bool}|\WP_Error
	 */
	private function check_slot( string $slot, $value ) {
		if ( ! is_array( $value ) || ( array() !== $value && array_is_list( $value ) ) ) {
			return $this->invalid( $slot, __( 'debe ser un objeto {layout_id, enabled}.', 'nexo-mcp' ) );
		}

		foreach ( array_keys( $value ) as $key ) {
			if ( ! in_array( (string) $key, array( 'layout_id', 'enabled' ), true ) ) {
				return $this->invalid( $slot . '.' . $key, __( 'no se admite. Admitidas: layout_id, enabled.', 'nexo-mcp' ) );
			}
		}

		$id = $value['layout_id'] ?? null;

		if ( null !== $id ) {
			if ( ! is_int( $id ) || $id < 1 ) {
				return $this->invalid( $slot . '.layout_id', __( 'debe ser el id entero de un layout (o null para no sobrescribir esa área).', 'nexo-mcp' ) );
			}

			if ( true !== $this->call( $this->layouts, $id, $slot ) ) {
				return $this->invalid( $slot . '.layout_id', sprintf( /* translators: 1: id, 2: área. */ __( 'el layout %1$d no existe, no está publicado o no es un layout de tipo %2$s.', 'nexo-mcp' ), $id, $slot ) );
			}
		}

		$enabled = $value['enabled'] ?? true;

		if ( ! is_bool( $enabled ) ) {
			return $this->invalid( $slot . '.enabled', __( 'debe ser un booleano (false oculta esa área).', 'nexo-mcp' ) );
		}

		return array(
			'layout_id' => $id,
			'enabled'   => $enabled,
		);
	}

	/**
	 * Si la plantilla afecta a todo el sitio: es la por defecto o su `use_on` trae un `…:all`, `archive:all` o `404`.
	 *
	 * @param bool               $is_default Plantilla por defecto.
	 * @param array<int, string> $use_on  Contextos.
	 */
	private function is_site_wide( bool $is_default, array $use_on ): bool {
		foreach ( $use_on as $context ) {
			$parsed = self::parse( $context );

			if ( null !== $parsed && $parsed['site_wide'] ) {
				return true;
			}
		}

		return $is_default;
	}

	/**
	 * Si el cuerpo ocuparía el lugar del contenido: la plantilla por defecto o una asignada a `homepage`, un singular o
	 * una pantalla de WooCommerce.
	 *
	 * @param array<string, mixed> $params Parámetros.
	 */
	private function replaces_content( array $params ): bool {
		foreach ( $params['use_on'] as $context ) {
			$parsed = self::parse( $context );

			if ( null !== $parsed && $parsed['content'] ) {
				return true;
			}
		}

		return true === $params['default'];
	}

	/**
	 * Reconoce una plantilla guardada.
	 *
	 * @param mixed $metas Metas.
	 * @param mixed $title Título.
	 *
	 * @return array<string, mixed>|null
	 */
	private function recognise( $metas, $title ): ?array {
		if ( ! is_array( $metas ) || ! is_string( $title ) ) {
			return null;
		}

		$known = array( '_et_default', '_et_enabled', '_et_use_on', '_et_exclude_from' );

		foreach ( self::SLOTS as $slot ) {
			$known[] = '_et_' . $slot . '_layout_id';
			$known[] = '_et_' . $slot . '_layout_enabled';
		}

		foreach ( array_keys( $metas ) as $key ) {
			if ( str_starts_with( (string) $key, '_et_' ) && ! in_array( $key, $known, true ) && ! in_array( $key, self::IGNORED_METAS, true ) ) {
				return null;
			}
		}

		$input = array( 'title' => $title );

		foreach ( array(
			'default' => '_et_default',
			'enabled' => '_et_enabled',
		) as $name => $key ) {
			$raw = $metas[ $key ] ?? null;

			if ( ! in_array( $raw, array( '0', '1' ), true ) ) {
				return null;
			}

			$input[ $name ] = '1' === $raw;
		}

		foreach ( array(
			'use_on'       => '_et_use_on',
			'exclude_from' => '_et_exclude_from',
		) as $name => $key ) {
			$raw = $metas[ $key ] ?? array();

			if ( ! is_array( $raw ) || ( array() !== $raw && ! array_is_list( $raw ) ) ) {
				return null;
			}

			$input[ $name ] = $raw;
		}

		foreach ( self::SLOTS as $slot ) {
			$id      = $metas[ '_et_' . $slot . '_layout_id' ] ?? '0';
			$enabled = $metas[ '_et_' . $slot . '_layout_enabled' ] ?? '1';

			if ( ! is_string( $id ) || 1 !== preg_match( '/^(?:0|[1-9][0-9]{0,9})\z/', $id ) || ! in_array( $enabled, array( '0', '1' ), true ) ) {
				return null;
			}

			$input[ $slot ] = array(
				'layout_id' => '0' === $id ? null : (int) $id,
				'enabled'   => '1' === $enabled,
			);
		}

		$params = $this->check( $input );

		return $params instanceof \WP_Error ? null : $params;
	}

	/**
	 * Entrada del resumen de un contexto guardado: id sólo si es de forma segura; `supported` si el catálogo y las
	 * fuentes lo aceptan (si una fuente falla, no); `priority` la del catálogo aunque el id no exista.
	 *
	 * @param mixed $context Contexto crudo.
	 *
	 * @return array{id: string|null, supported: bool, priority: int|null}
	 */
	private function summarise_context( $context ): array {
		$safe = is_string( $context ) && 1 === preg_match( '/^[A-Za-z0-9_:\-]{1,200}\z/', $context );

		return array(
			'id'        => $safe ? $context : null,
			'supported' => $safe && true === $this->safely( fn(): bool => ! $this->check_context( 'x', $context ) instanceof \WP_Error ),
			'priority'  => self::priority( $context ),
		);
	}

	/**
	 * Plantillas utilizables para las prioridades: lo que no encaje se ignora.
	 *
	 * @param mixed $templates Lista cruda.
	 *
	 * @return array<int, array{key: string|int, enabled: bool, default: bool, use_on: array<int, string>, exclude_from: array<int, string>}>
	 */
	private static function usable( $templates ): array {
		$out = array();

		foreach ( is_array( $templates ) ? $templates : array() as $template ) {
			if ( ! is_array( $template ) || ! ( is_string( $template['key'] ?? null ) || is_int( $template['key'] ?? null ) ) ) {
				continue;
			}

			$out[] = array(
				'key'          => $template['key'],
				'enabled'      => true === ( $template['enabled'] ?? null ),
				'default'      => true === ( $template['default'] ?? null ),
				'use_on'       => self::strings( $template['use_on'] ?? null ),
				'exclude_from' => self::strings( $template['exclude_from'] ?? null ),
			);
		}

		return array_values( array_filter( $out, static fn( array $t ): bool => $t['enabled'] ) );
	}

	/**
	 * Sólo los textos de una lista.
	 *
	 * @param mixed $items Valor.
	 *
	 * @return array<int, string>
	 */
	private static function strings( $items ): array {
		return is_array( $items ) && array_is_list( $items ) ? array_values( array_filter( $items, 'is_string' ) ) : array();
	}

	/**
	 * Lista cruda de una meta de condiciones: una lista, o un texto suelto como lista de uno.
	 *
	 * @param mixed $value Valor.
	 *
	 * @return array<int, mixed>
	 */
	private static function raw_list( $value ): array {
		if ( is_string( $value ) ) {
			return array( $value );
		}

		return is_array( $value ) ? array_values( $value ) : array();
	}

	/**
	 * Texto para mostrar: sin control ni `< >`, de hasta 100 caracteres.
	 *
	 * @param string $text Texto.
	 */
	private static function display_text( string $text ): string {
		$clean = preg_replace( '/[\x00-\x1F\x7F<>]/u', '', $text );

		return mb_substr( trim( is_string( $clean ) ? $clean : '' ), 0, self::MAX_TITLE, 'UTF-8' );
	}

	/**
	 * Si el contexto `$broad` (un `…:all`) incluye a `$narrow` (por ejemplo `archive:all` y `archive:post_type:post`).
	 *
	 * @param string $broad  Contexto amplio.
	 * @param string $narrow Contexto específico.
	 */
	private static function contains( string $broad, string $narrow ): bool {
		return $broad !== $narrow && str_ends_with( $broad, ':all' ) && str_starts_with( $narrow, substr( $broad, 0, -3 ) );
	}

	/**
	 * Analiza un contexto contra el catálogo cerrado, sin consultar nada.
	 *
	 * @param mixed $context Valor.
	 *
	 * @return array{priority: int, site_wide: bool, content: bool, checks: array<int, array<int, string>>}|null
	 */
	private static function parse( $context ): ?array {
		if ( ! is_string( $context ) || strlen( $context ) > 200 ) {
			return null;
		}

		$p = explode( ':', $context );
		$n = count( $p );

		foreach ( $p as $part ) {
			if ( 1 !== preg_match( '/^[a-z0-9_\-]{1,32}\z/', $part ) ) {
				return null;
			}
		}

		$id = static fn( string $v ): bool => 1 === preg_match( '/^[1-9][0-9]{0,9}\z/', $v );

		$make = static fn( int $priority, bool $site_wide, bool $content, array $checks = array() ): array => array(
			'priority'  => $priority,
			'site_wide' => $site_wide,
			'content'   => $content,
			'checks'    => $checks,
		);

		if ( 1 === $n ) {
			return match ( $p[0] ) {
				'homepage' => $make( 110, false, true ),
				'404'      => $make( 1, true, false ),
				'search'   => $make( 1, false, false ),
				default    => null,
			};
		}

		$head = $p[0] . ':' . $p[1];

		if ( 'singular:post_type' === $head && 4 === $n && 'all' === $p[3] ) {
			return $make( 70, true, true, array( array( 'post_type', $p[2] ) ) );
		}

		if ( 'singular:post_type' === $head && 5 === $n && 'id' === $p[3] && $id( $p[4] ) ) {
			return $make( 100, false, true, array( array( 'post_type', $p[2] ), array( 'post', $p[4], $p[2] ) ) );
		}

		if ( 'singular:taxonomy' === $head && 6 === $n && 'term' === $p[3] && 'id' === $p[4] && $id( $p[5] ) ) {
			return $make( 80, false, true, array( array( 'taxonomy', $p[2] ), array( 'term', $p[5], $p[2] ) ) );
		}

		if ( 'archive:all' === $context ) {
			return $make( 30, true, false );
		}

		if ( 'archive:post_type' === $head && 3 === $n ) {
			return $make( 60, false, false, array( array( 'post_type', $p[2] ) ) );
		}

		if ( 'archive:taxonomy' === $head && 4 === $n && 'all' === $p[3] ) {
			return $make( 70, true, false, array( array( 'taxonomy', $p[2] ) ) );
		}

		if ( 'archive:taxonomy' === $head && 6 === $n && 'term' === $p[3] && 'id' === $p[4] && $id( $p[5] ) ) {
			return $make( 75, false, false, array( array( 'taxonomy', $p[2] ), array( 'term', $p[5], $p[2] ) ) );
		}

		if ( 'archive:user:all' === $context ) {
			return $make( 50, true, false );
		}

		if ( 'archive:user' === $head && 4 === $n && 'id' === $p[2] && $id( $p[3] ) ) {
			return $make( 55, false, false, array( array( 'user', $p[3] ) ) );
		}

		if ( 'archive:date:all' === $context ) {
			return $make( 40, true, false );
		}

		if ( 'woocommerce' === $p[0] && 2 === $n ) {
			return match ( $p[1] ) {
				'shop', 'cart', 'checkout' => $make( 120, false, true, array( array( 'woo' ) ) ),
				'my_account'               => $make( 130, false, true, array( array( 'woo' ) ) ),
				default                    => null,
			};
		}

		return null;
	}

	/**
	 * Si una consulta devolvió un tipo o taxonomía público.
	 *
	 * @param mixed $found Resultado de la fuente.
	 */
	private function is_public( $found ): bool {
		return is_array( $found ) && true === ( $found['public'] ?? null );
	}

	/**
	 * Si una entrada publicada es del tipo esperado.
	 *
	 * @param mixed  $found Resultado de la fuente.
	 * @param string $type  Tipo.
	 */
	private function post_is( $found, string $type ): bool {
		return is_array( $found ) && ( $found['type'] ?? null ) === $type;
	}

	/**
	 * Llama a una fuente de WordPress: si lanza, es como si no hubiera resultado.
	 *
	 * @param callable $source Fuente.
	 * @param mixed    ...$args Argumentos.
	 *
	 * @return mixed
	 */
	private function call( callable $source, ...$args ) {
		return $this->safely( static fn() => $source( ...$args ) );
	}

	/**
	 * Ejecuta un trabajo sin dejar escapar nada.
	 *
	 * @template T
	 *
	 * @param callable(): T $work Trabajo.
	 *
	 * @return T|null
	 */
	private function safely( callable $work ) {
		try {
			return $work();
		} catch ( \Throwable $e ) {
			unset( $e );

			return null;
		}
	}

	/**
	 * Error de un campo.
	 *
	 * @param string $path   Ruta (`use_on.2`).
	 * @param string $reason Motivo.
	 */
	private function invalid( string $path, string $reason ): \WP_Error {
		return new \WP_Error( self::CODE_INVALID, $path . ': ' . $reason, array( 'path' => $path ) );
	}
}
